'use client'

import * as React from 'react'

// stat renders the number, the label, the change beside it and the accessible
// name. This file adds the rising mark and nothing else.
import { Stat, type StatPresentation } from './stat'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Streak, and `tsc --noEmit` passes on it, so
// the gate cannot catch it.
import './streak.css'

// The cue runtime. `./feel` is a local re-export shim in this repo and the
// installed sibling file in a host application, so the one specifier resolves
// in both places. With no provider above it, `useGameFeel` is a no-op.
import { useGameFeel } from './feel'

/**
 * Streak: how many in a row, drawn as a reward pill with a rising mark.
 *
 * A thin wrapper over `stat` (BDS-021). It renders no number of its own, owns
 * no tabular numerals and invents no accessible-name vocabulary: `data-gs-value`,
 * `data-gs-delta`, the label and the announcement all come from `stat`. What
 * streak adds is the mark, a triangle pointing up, lit while the run is alive.
 *
 * ## The drawing, not the flame
 *
 * Specimen 3b draws the streak as a pill in the reward colour holding a small
 * upward triangle and the count written `x5`, and draws a broken streak as a
 * smaller, dimmer pill reading `x0` with no mark at all. This used to draw a
 * flame that went out. The drawing wins: the lit pill and the broken one differ
 * in size, in fill, in the size of the number and in whether there is a mark,
 * so a player who cannot see the colour, a greyscale screenshot and a printed
 * page all still show which one they are looking at.
 *
 * A broken streak is `value={0}`, which is a real state and reads like every
 * other zero: `data-gs-value="0"`, announced as "streak, 0". There is no
 * separate broken attribute, because the number already says it and a second
 * name for one fact drifts from the first. The `x` in front of the number is
 * rendering only: `display` carries it, so the accessible name still says the
 * bare count.
 *
 * A streak carries no `max`, deliberately. It has no ceiling, so there is
 * nothing for `data-gs-max` to hold and "7 of 7" would read as complete.
 *
 * It performs nothing. It does not count, break, or decide when a streak is
 * about to go. The host owns the number.
 */

export interface StreakProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'children'> {
  /** How many in a row. Zero is a broken streak, which is a state. */
  value: number
  /** How much it just moved, signed. One more in a row is `1`. */
  delta?: number
  /** About to go. The host decides where that line is. */
  critical?: boolean
  /** The word beside the mark. Defaults to "streak". */
  label?: string
  /**
   * The silhouette of the number inside. The design draws the streak as a pill
   * rather than as a label above a bare number (GSUI-100); the mark sits beside
   * it either way.
   */
  presentation?: StatPresentation
}

/**
 * The rising mark: a triangle 16 wide and 14 tall, which is what the drawing
 * builds out of borders. Drawn on a 16px box so the icon token sizes it.
 * currentColor throughout: the mark names no colour, so a theme owns it.
 */
const RISE = 'M8 1L16 15H0Z'

function Rise() {
  return (
    <svg className="gs-streak__rise" viewBox="0 0 16 16" focusable="false" aria-hidden="true">
      <path d={RISE} fill="currentColor" />
    </svg>
  )
}

export function Streak({
  value,
  delta,
  critical,
  label,
  presentation = 'pill',
  className,
  ...rest
}: StreakProps) {
  const lit = value > 0
  // The design, specimen 3d: "grow: motion.pop · sfx.streak(n)". The host owns
  // the number, so growing is a change in the prop and nothing else. A HUD
  // mounting at streak 5 has not just gone from 4 to 5, so the first render
  // fires nothing; so does a streak that breaks, which is a drop and has its
  // own drawing already.
  const { cue } = useGameFeel()
  const previous = React.useRef<number | null>(null)
  const [popping, setPopping] = React.useState(false)

  React.useEffect(() => {
    const was = previous.current
    previous.current = value
    if (was === null || value <= was) return
    // `streak` is pitched by n in the token file and n cannot be passed: the
    // runtime's cue takes a name and a kind, nothing more. The cue fires
    // unpitched and the gap is GSUI-173.
    cue('streak', 'sfx')
    // Specimen 4d draws the same moment as haptic.medium, which the catalogue
    // words as "commit, streak, GO".
    cue('medium', 'haptic')
    setPopping(true)
  }, [value, cue])

  return (
    <div
      {...rest}
      className={['gs-streak', className].filter(Boolean).join(' ')}
      data-gs-component="streak"
      // Only while it is popping. The attribute is a claim that this element is
      // animating now, and an element carrying it with no animation on it is an
      // element reduced motion takes nothing away from. Cleared by the
      // animation itself rather than by a duration written down twice.
      data-gs-animates={popping ? 'motion' : undefined}
      onAnimationEnd={(event) => {
        rest.onAnimationEnd?.(event)
        if (event.target === event.currentTarget) setPopping(false)
      }}
    >
      {/*
        The reserved `glyph` part: the state carried without colour, and drawn
        before the number because that is the order the drawing puts them in.
        Stat renders a glyph of its own when critical, nested inside itself, so
        a test reaches this one as a direct child of the streak root and the
        two never collide.

        Only while the streak is alive: the drawing's broken pill has no mark,
        and the pill's own size and fill are what say it went out.

        `emphasis`, not `motion`: the mark changes and never moves, so it
        survives reduced motion, which is the whole point of drawing it.
      */}
      {lit ? (
        <span
          className="gs-streak__glyph"
          data-gs-scope="streak" data-gs-part="glyph"
          data-gs-animates="emphasis"
          aria-hidden="true"
        >
          <Rise />
        </span>
      ) : null}
      <Stat
        kind="streak"
        label={label}
        value={value}
        display={`x${value}`}
        delta={delta}
        critical={critical}
        presentation={presentation}
      />
    </div>
  )
}

/* Streak. Every value comes from a token; nothing here is a literal colour.
   The number, its label and its change are stat's; this file lays out the pill
   and the rising mark, and nothing else. */

/* The mark belongs inside the pill.

   It is a sibling of the stat in the DOM, deliberately: stat renders a glyph of
   its own when a value turns critical, and keeping the mark outside is what
   stops a test reaching for one and finding the other. Left to itself, though,
   that DOM drew the mark floating beside the pill with nothing around it, and
   in the game's HUD it read as an icon that had come loose.

   So the streak root carries the pill and the stat inside it gives its own up.
   One shape, both things in it, and the parts stay where the contract says.

   Only when the stat is actually a pill: in the plain presentation there is no
   shape to be inside, and drawing one here would invent a chip the host did not
   ask for.

   Specimen 3b draws the pill and design/twins/3b.json measures ours against
   it: 52px tall (size.chip), padded at space.4, round, filled with the reward
   colour and outlined in colour.edge at the 3px stroke, the mark and the number
   8px apart, both in on-bright. The number is the title size, Unbounded 20/900
   in arcade, not the stat size the other HUD numbers use. */
.gs-streak {
  display: inline-flex;
  align-items: center;
  gap: var(--gs-space-2);
}

.gs-streak:has(.gs-stat[data-gs-presentation='pill']) {
  position: relative;
  box-sizing: border-box;
  min-block-size: var(--gs-size-chip);
  padding: 0 var(--gs-space-4);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-reward);
  color: var(--gs-color-on-bright);
  /* Emphasis: the pill changes fill and size when the streak breaks, and a
     break a player only sees if they can see animation is not a break. */
  transition:
    background-color var(--gs-motion-emphasis) ease-out,
    border-color var(--gs-motion-emphasis) ease-out;
}

/* The stat inside gives up its own box: the streak root is the pill. Its ink
   too: a critical pill paints itself in colour.ink for the timer's red fill,
   and a critical streak is still on the reward fill, so the root's on-bright
   is the colour that reaches the number. */
.gs-streak:has(.gs-stat[data-gs-presentation='pill']) .gs-stat[data-gs-presentation='pill'] {
  min-height: 0;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
}

.gs-streak:has(.gs-stat[data-gs-presentation='pill']) .gs-stat__value {
  font-family: var(--gs-type-title-font-family);
  font-size: var(--gs-type-title-font-size);
  font-weight: var(--gs-type-title-font-weight);
  line-height: normal;
  /* The ink comes from the fill, not the page: on-bright on the reward colour,
     muted once the streak is broken, from the root either way. */
  color: inherit;
}

/* A broken streak is a smaller, dimmer pill: 40px tall (size.controlSmall),
   padded at space.3, on the plain surface, the number at figure size in muted,
   and no mark. Four differences before any colour, so it reads in greyscale. */
.gs-streak:has(.gs-stat[data-gs-presentation='pill'][data-gs-value='0']) {
  min-block-size: var(--gs-size-control-small);
  padding: 0 var(--gs-space-3);
  background: var(--gs-color-surface);
  color: var(--gs-color-muted);
}

.gs-streak:has(.gs-stat[data-gs-presentation='pill'][data-gs-value='0']) .gs-stat__value {
  font-family: var(--gs-type-figure-font-family);
  font-size: var(--gs-type-figure-font-size);
  font-weight: var(--gs-type-figure-font-weight);
}

/* Growing pops (specimen 3d: "grow: motion.pop · sfx.streak(n)"), on the
   token's own curve and travel: 400ms, (.2,1.4,.4,1), scale .6 → 1.12 → 1.
   The attribute is on the root only while the pop is running, so reduced motion
   zeroes this duration and the streak simply arrives at its new number, which
   is the change a player who cannot see movement still reads. */
.gs-streak[data-gs-animates='motion'] {
  animation: gs-streak-pop var(--gs-motion-pop) cubic-bezier(0.2, 1.4, 0.4, 1);
}

@keyframes gs-streak-pop {
  0% { transform: scale(0.6); }
  60% { transform: scale(1.12); }
  100% { transform: scale(1); }
}

.gs-streak__glyph {
  display: inline-flex;
  align-items: center;
  /* Emphasis: colour only, no movement, so it still reads under reduced
     motion. */
  transition: color var(--gs-motion-emphasis) ease-out;
}

/* The rising mark: the drawing builds a 16 by 14 triangle out of borders; ours
   is the same triangle on the 16px utility icon box. */
.gs-streak__rise {
  display: block;
  width: var(--gs-size-icon-utility);
  height: var(--gs-size-icon-utility);
}

/* The delta reads in the pill's own ink. Stat colours a rising delta positive
   green, which on the reward fill is green on yellow and does not pass;
   the pill is already the colour of good news, so the number is on-bright. */
.gs-streak .gs-stat__delta,
.gs-streak .gs-stat[data-gs-delta] .gs-stat__delta {
  color: var(--gs-color-on-bright);
}
